package com.troday.api.service;
import com.fasterxml.jackson.databind.JsonNode; import com.troday.api.dto.ApiResponseDto; import com.troday.api.entity.*; import com.troday.api.repository.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.transaction.Transactional; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*;
@Service public class ContractChangeService {
 private final AccountService accounts; private final ContractRepository contracts; private final ContractChangeRequestRepository changes; private final RoomRepository rooms;
 public ContractChangeService(AccountService a,ContractRepository c,ContractChangeRequestRepository x,RoomRepository rooms){accounts=a;contracts=c;changes=x;this.rooms=rooms;}
 public ApiResponseDto<?> list(HttpServletRequest r,Long cid){access(r,cid);return ok("GET",changes.findByContractIdOrderByIdDesc(cid).stream().map(this::data).toList());}
 @Transactional public ApiResponseDto<?> create(HttpServletRequest r,Long cid,JsonNode b){Long me=accounts.authenticatedUserId(r);Contract c=access(r,cid);if(!Objects.equals(c.getViewingTenantId(),me))throw forbidden("Chỉ đại diện mới được yêu cầu điều chỉnh");if(!"ACTIVE".equals(c.getStatus()))throw conflict("Chỉ hợp đồng ACTIVE mới được điều chỉnh");String type=text(b,"type");if(!Set.of("RENEWAL","TERMINATION","TRANSFER").contains(type))throw bad("type không hợp lệ");Long base=requiredLong(b,"baseRevisionId");if(!Objects.equals(c.getCurrentRevisionId(),base))throw conflict("Revision nền đã thay đổi");if(changes.findByContractIdOrderByIdDesc(cid).stream().anyMatch(x->Set.of("PENDING","APPROVED_WAITING_CONFIRMATION","READY_TO_APPLY").contains(x.getStatus())))throw conflict("Đã có yêu cầu điều chỉnh đang mở");Long target=b.hasNonNull("targetRoomId")?b.get("targetRoomId").asLong():null;if("TRANSFER".equals(type)&&target==null)throw bad("targetRoomId là bắt buộc khi đổi phòng");if(!"TRANSFER".equals(type)&&target!=null)throw bad("targetRoomId chỉ dùng cho TRANSFER");ContractChangeRequest x=new ContractChangeRequest();x.setContractId(cid);x.setRequestedById(me);x.setRepresentativeRoomTenantId(c.getRepresentativeRoomTenantId());x.setBaseRevisionId(base);x.setTargetRoomId(target);x.setType(type);x.setRequestedEffectiveDate(date(b,"effectiveDate"));x.setProposalSnapshot(b.toString());x.setMessage(text(b,"reason"));return ok("POST",data(changes.save(x)));}
 public ApiResponseDto<?> detail(HttpServletRequest r,Long id){ContractChangeRequest x=change(id);access(r,x.getContractId());return ok("GET",data(x));}
 @Transactional public ApiResponseDto<?> decision(HttpServletRequest r,Long id,JsonNode b){Long owner=accounts.authenticatedUserId(r);ContractChangeRequest x=change(id);Contract c=access(r,x.getContractId());if(!Objects.equals(c.getLandlordId(),owner))throw forbidden("Chỉ chủ trọ được duyệt");if(!"PENDING".equals(x.getStatus()))throw conflict("Yêu cầu không còn chờ");String d=text(b,"decision");if(!Set.of("APPROVE","REJECT").contains(d))throw bad("decision phải là APPROVE hoặc REJECT");x.setReviewedById(owner);x.setReviewedAt(LocalDateTime.now());if("REJECT".equals(d)){x.setStatus("REJECTED");x.setRejectionReason(text(b,"reason"));if(x.getRejectionReason().isBlank())throw bad("reason là bắt buộc");}else{x.setStatus("APPROVED_WAITING_CONFIRMATION");x.setExpiresAt(LocalDateTime.now().plusDays(2));}return ok("POST",data(changes.save(x)));}
 @Transactional public ApiResponseDto<?> confirm(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);ContractChangeRequest x=change(id);Contract c=access(r,x.getContractId());if(!Objects.equals(c.getViewingTenantId(),me))throw forbidden("Chỉ đại diện mới được xác nhận");if(!"APPROVED_WAITING_CONFIRMATION".equals(x.getStatus()))throw conflict("Yêu cầu chưa được chủ trọ duyệt");if(x.getExpiresAt()!=null&&x.getExpiresAt().isBefore(LocalDateTime.now()))throw conflict("Phương án đã hết hạn");x.setStatus("READY_TO_APPLY");x.setTenantConfirmedById(me);x.setTenantConfirmedAt(LocalDateTime.now());return ok("POST",data(changes.save(x)));}
 @Transactional public ApiResponseDto<?> cancel(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);ContractChangeRequest x=change(id);if(!Objects.equals(x.getRequestedById(),me))throw forbidden("Chỉ người yêu cầu mới được hủy");if(!Set.of("PENDING","APPROVED_WAITING_CONFIRMATION","READY_TO_APPLY").contains(x.getStatus()))throw conflict("Yêu cầu không thể hủy");x.setStatus("CANCELLED");x.setCancelledById(me);x.setCancelledAt(LocalDateTime.now());x.setCancellationReason(text(b,"reason"));return ok("POST",data(changes.save(x)));}
 @Transactional public ApiResponseDto<?> apply(HttpServletRequest r,Long id){Long owner=accounts.authenticatedUserId(r);ContractChangeRequest x=change(id);Contract c=access(r,x.getContractId());if(!Objects.equals(c.getLandlordId(),owner))throw forbidden("Chỉ chủ trọ được áp dụng");if(!"READY_TO_APPLY".equals(x.getStatus()))throw conflict("Yêu cầu chưa đủ xác nhận");if(!Objects.equals(c.getCurrentRevisionId(),x.getBaseRevisionId()))throw conflict("Revision nền đã thay đổi");if("RENEWAL".equals(x.getType())){c.setEndDate(x.getRequestedEffectiveDate());}else if("TERMINATION".equals(x.getType())){c.setStatus("TERMINATED");}else{Room room=rooms.findById(x.getTargetRoomId()).orElseThrow(()->notFound("Không tìm thấy phòng đích"));if(!room.getHouseId().equals(c.getHouseId()))throw bad("Phòng đích phải cùng nhà");Contract result=new Contract();result.setContractNumber(c.getContractNumber()+"-TRANSFER-"+System.currentTimeMillis());result.setRoomId(room.getId());result.setHouseId(c.getHouseId());result.setLandlordId(c.getLandlordId());result.setViewingTenantId(c.getViewingTenantId());result.setSource("TRANSFER");result.setPreviousContractId(c.getId());result.setStatus("DRAFT");result.setStartDate(x.getRequestedEffectiveDate());result.setEndDate(c.getEndDate());result.setRentAmount(c.getRentAmount());result.setDepositAmount(c.getDepositAmount());result=contracts.save(result);x.setResultContractId(result.getId());c.setStatus("TERMINATED");}x.setStatus("COMPLETED");x.setAppliedById(owner);x.setAppliedAt(LocalDateTime.now());contracts.save(c);return ok("POST",data(changes.save(x)));}
 public ApiResponseDto<?> transferOptions(HttpServletRequest r,Long cid){Contract c=access(r,cid);return ok("GET",rooms.findByHouseId(c.getHouseId()).stream().filter(room->!room.getId().equals(c.getRoomId())&&!contracts.findAll().stream().anyMatch(x->room.getId().equals(x.getRoomId())&&Set.of("DRAFT","PENDING_CONFIRMATION","CONFIRMED","ACTIVE").contains(x.getStatus()))).map(room->{Map<String,Object>m=new LinkedHashMap<>();m.put("roomId",room.getId());m.put("code",room.getRoomNumber());m.put("area",room.getArea());m.put("rentAmount",room.getRentPrice());m.put("openMemberCount",0);return m;}).toList());}
 private Contract access(HttpServletRequest r,Long id){Long me=accounts.authenticatedUserId(r);Contract c=contracts.findById(id).orElseThrow(()->notFound("Không tìm thấy hợp đồng"));if(!Objects.equals(c.getLandlordId(),me)&&!Objects.equals(c.getViewingTenantId(),me))throw forbidden("Không có quyền với hợp đồng");return c;}private ContractChangeRequest change(Long id){return changes.findById(id).orElseThrow(()->notFound("Không tìm thấy yêu cầu điều chỉnh"));}private LocalDate date(JsonNode b,String k){try{return LocalDate.parse(text(b,k));}catch(Exception e){throw bad(k+" không hợp lệ");}}private Long requiredLong(JsonNode b,String k){if(b==null||!b.hasNonNull(k))throw bad(k+" là bắt buộc");return b.get(k).asLong();}private String text(JsonNode b,String k){return b!=null&&b.hasNonNull(k)?b.get(k).asText():"";}
 private Map<String,Object> data(ContractChangeRequest x){Map<String,Object>m=new LinkedHashMap<>();m.put("id",x.getId());m.put("contractId",x.getContractId());m.put("type",x.getType());m.put("status",x.getStatus());m.put("requestedById",x.getRequestedById());m.put("baseRevisionId",x.getBaseRevisionId());m.put("targetRoomId",x.getTargetRoomId());m.put("resultContractId",x.getResultContractId());m.put("requestedEffectiveDate",x.getRequestedEffectiveDate());m.put("proposalSnapshot",x.getProposalSnapshot());m.put("rejectionReason",x.getRejectionReason());return m;}private ApiResponseDto<?> ok(String m,Object d){return ApiResponseDto.ok("/api/v1",m,d);}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);}private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
